module TopModule (
    input  logic [3:0] in,
    output logic [3:0] out_both,
    output logic [3:0] out_any,
    output logic [3:0] out_different
);

  assign out_both      = {1'b0, in[2:0] & in[3:1]};
  assign out_any       = {(in[3:1] | in[2:0]), 1'b0};
  assign out_different = in ^ {in[0], in[3:1]};

endmodule

module tb_TopModule;
  logic [3:0] in;
  logic [3:0] out_both;
  logic [3:0] out_any;
  logic [3:0] out_different;

  TopModule dut (
    .in(in),
    .out_both(out_both),
    .out_any(out_any),
    .out_different(out_different)
  );

  initial begin
    integer i;
    logic [3:0] exp_both;
    logic [3:0] exp_any;
    logic [3:0] exp_diff;
    logic err_flag = 0;

    for (i = 0; i < 16; i = i + 1) begin
      in = i[3:0];
      #1;

      // Expected both: out_both[i] = in[i] & in[i+1] for i=0..2, out_both[3]=0
      exp_both[3] = 1'b0;
      exp_both[2] = in[2] & in[3];
      exp_both[1] = in[1] & in[2];
      exp_both[0] = in[0] & in[1];

      // Expected any: out_any[i] = in[i] | in[i-1] for i=1..3, out_any[0]=0
      exp_any[3] = in[3] | in[2];
      exp_any[2] = in[2] | in[1];
      exp_any[1] = in[1] | in[0];
      exp_any[0] = 1'b0;

      // Expected different: wrap around left neighbour
      exp_diff[3] = in[3] ^ in[0];
      exp_diff[2] = in[2] ^ in[3];
      exp_diff[1] = in[1] ^ in[2];
      exp_diff[0] = in[0] ^ in[1];

      if (out_both !== exp_both || out_any !== exp_any || out_different !== exp_diff) begin
        $display("FAIL: in=%b | out_both=%b (exp %b), out_any=%b (exp %b), out_different=%b (exp %b)",
                 in, out_both, exp_both, out_any, exp_any, out_different, exp_diff);
        err_flag = 1;
      end
    end

    if (err_flag) begin
      $display("SELFTEST FAIL: Mismatches detected.");
    end else begin
      $display("SELFTEST PASS");
    end
    $finish;
  end
endmodule
